import { useEffect, useRef } from "react";
import { appInstallUrl } from "@/components/connectors/app-install";
import { FullPageSpinner } from "@/components/ui/full-page-spinner";
import { useOrgContext } from "@/hooks/use-org-context";
import { fetchInstallableConnectorCatalog } from "@/lib/api";
import { resolveAppInstallTarget } from "@/lib/onboarding-install";

export const Route = createFileRoute("/")({ component: HomePage });

function HomePage() {
	const { isAuthenticated, authReady, currentOwner, orgsReady } =
		useOrgContext();
	const navigate = useNavigate();
	const location = useLocation();
	const redirectStarted = useRef(false);

