	// `newUserCallbackURL` (set in login.tsx), carrying the signup provider on
	// the query string. better-auth only sends genuine new users here —
	// returning users hit `callbackURL` — so no server-stored intent is needed;
	// we resolve which connector to install from the connector catalog (scoped
	// to the owner slug, which this slug-less route doesn't carry in its URL),
	// then jump into the gateway's signed install start-route.
	const onboardProvider = new URLSearchParams(window.location.search).get(
		"onboard_provider",
	);

	useEffect(() => {
		if (!authReady) return;

		// This is a redirect-only home route. The responsive shell's narrow
		// container-query flip (false→true after mount) can transiently
		// re-render / remount this component while a redirect is still in
		// flight. A stale instance still resolves `currentOwner` from the new
		// URL and would re-issue `navigate({ to: "/$owner" })` even though the
		// URL has already moved on — which ping-pongs with `$owner`'s
		// beforeLoad redirect into an infinite navigation loop
		// at narrow widths (the embedded side panel pegged on a spinner).
		// Only redirect while this route is actually active (URL is "/").
		if (location.pathname !== "/") return;

		if (isAuthenticated && currentOwner) {
			// Chrome extension deep links: the side-panel bootstrap lands here with
			// a hash because the extension knows device/run/agent ids but not the
			// org slug. We resolve `currentOwner` and forward.
			//   `#worker=<deviceId>`              → Infrastructure › Runtimes › device
			//   `#agent=&thread=&message=`        → Agent chat (+ optional scroll)
			//   `#run=<runId>`                    → Memory for that run + peek pane
			//
			// CRITICAL (sidepanel): do NOT re-fire router.navigate while still on
			// `/` with the same hash — TanStack load + remount loops hit React
			// #185 (max update depth) and leave the iframe blank. Clear the hash
			// and hard-replace once so a narrow embedded remount cannot re-enter.
			const hashParams = new URLSearchParams(
				window.location.hash.replace(/^#/, ""),
			);
			const agentHash = hashParams.get("agent")?.trim();
			const threadHash = hashParams.get("thread")?.trim();
			const messageHash =
				hashParams.get("message")?.trim() ||
				hashParams.get("message_id")?.trim();
			const runIdRaw = hashParams.get("run")?.trim();
			const deviceId = hashParams.get("worker")?.trim();
			const hasDeepLink =
				(!!agentHash && !!threadHash) ||
				(!!runIdRaw && /^\d+$/.test(runIdRaw)) ||
				!!deviceId;

			if (hasDeepLink) {
				if (redirectStarted.current) return;
				redirectStarted.current = true;
				// Drop the fragment before navigating so a remount of `/` cannot
				// re-read agent/thread/run and navigate again.
				window.history.replaceState(
					null,
					"",
					`${window.location.pathname}${window.location.search}`,
				);

				if (agentHash && threadHash) {
					const qs = messageHash
						? `?message_id=${encodeURIComponent(messageHash)}`
						: "";
