						`/${encodeURIComponent(currentOwner)}/agents/${encodeURIComponent(agentHash)}/chat/c/${encodeURIComponent(threadHash)}${qs}`,
					);
					return;
				}
				if (runIdRaw && /^\d+$/.test(runIdRaw)) {
					const qs = new URLSearchParams({
						run_ids: runIdRaw,
						peek: "1",
						peek_run_id: runIdRaw,
					});
