						`/${encodeURIComponent(currentOwner)}/activity?${qs.toString()}`,
					);
					return;
				}
				if (deviceId) {
					window.location.replace(
						`/${encodeURIComponent(currentOwner)}/connectors/runtime/devices/${encodeURIComponent(deviceId)}`,
					);
					return;
				}
