			to: "/auth/login",
			search: {
				callbackUrl: undefined,
				mode: undefined,
				error: undefined,
				errorDescription: undefined,
				loginHint: undefined,
				invitationOrg: undefined,
				intent: undefined,
			},
			replace: true,
		});
	}, [
		authReady,
		currentOwner,
		isAuthenticated,
		orgsReady,
		navigate,
		location.pathname,
		onboardProvider,
	]);

	return (
		<div data-public-loading="true">
			<FullPageSpinner delayMs={0} className="min-h-0 py-16" />
		</div>
	);
}

