import { useNavigate } from "@tanstack/react-router";
import { useEffect } from "react";
import { getPublicBootstrap } from "@/lib/public-bootstrap";

/**
 * Single source of truth for sending someone to `/auth/login`.
 *
 * The route's `validateSearch` accepts seven keys, and TanStack's typed
 * `navigate`/`<Link>` want the whole shape spelled out. Every call site used to
 * repeat all seven — five of them purely to write `undefined` — which is how
 * `$owner` ended up as the one owner-level route with no sign-in redirect at
 * all: there was nothing to reuse, only a literal to copy.
 */

export interface SignInSearchOptions {
	/** Where to return after a successful sign-in. */
	callbackUrl?: string;
	intent?: "sign-in" | "sign-up";
	invitationOrg?: string;
	loginHint?: string;
}

export interface SignInSearch {
	callbackUrl: string | undefined;
	mode: undefined;
	error: undefined;
	errorDescription: undefined;
	loginHint: string | undefined;
	invitationOrg: string | undefined;
	intent: "sign-in" | "sign-up" | undefined;
}

/** Build the `/auth/login` search params. Omitted keys are explicitly undefined. */
export function signInSearch(options: SignInSearchOptions = {}): SignInSearch {
	return {
		callbackUrl: options.callbackUrl,
		mode: undefined,
		error: undefined,
		errorDescription: undefined,
		loginHint: options.loginHint,
		invitationOrg: options.invitationOrg,
		intent: options.intent,
	};
}

/**
 * The current location, for a post-sign-in bounce back.
 *
 * Deliberately `window.location` and not the router's location: on a per-org
 * subdomain the router works in `/${owner}`-prefixed paths while the URL bar
 * (and therefore the path the browser will actually re-request after login)
 * stays unprefixed. Reading the router here would send `buremba.lobu.ai` users
 * back to `/buremba/...`, which the subdomain history would prefix a second
 * time.
 */
export function currentCallbackUrl(): string {
	return window.location.pathname + window.location.search;
}

export interface AnonymousSignInRedirectOptions {
	/**
	 * True once we know this page has nothing to show a signed-out visitor.
	 * Callers must have settled their own loading state first, and must not set
	 * this for a server/transport failure — an outage is not an authz problem,
	 * and bouncing there reads as "you are not allowed here".
	 */
	active: boolean;
	/**
	 * Owner slug. Skips the redirect when SSR injected a public bootstrap for
	 * this owner, which it only does for orgs whose visibility is 'public'.
	 */
	owner?: string;
}

/** Send a signed-out visitor to sign-in, returning them here afterwards. */
export function useAnonymousSignInRedirect({
	active,
	owner,
}: AnonymousSignInRedirectOptions): void {
	const navigate = useNavigate();

	useEffect(() => {
		if (!active) return;
		if (owner && getPublicBootstrap()?.ownerSlug === owner) return;
		void navigate({
			to: "/auth/login",
			search: signInSearch({
				callbackUrl: currentCallbackUrl(),
				intent: "sign-in",
			}),
			replace: true,
		});
	}, [active, owner, navigate]);
}

