/**
 * Send a signed-out visitor to sign-in, returning them here afterwards.
 *
 * Returns whether a redirect is in flight, so the caller can render nothing
 * instead of flashing its own error state on the way out — the bare org root
 * used to paint the raw 401 body for a frame before navigating.
 */
export function useAnonymousSignInRedirect({
	active,
	owner,
}: AnonymousSignInRedirectOptions): boolean {
	const navigate = useNavigate();
	const isPublicOrg = !!owner && getPublicBootstrap()?.ownerSlug === owner;
	const redirecting = active && !isPublicOrg;

	useEffect(() => {
		if (!redirecting) return;
		void navigate({
			to: "/auth/login",
			search: signInSearch({
				callbackUrl: currentCallbackUrl(),
				intent: "sign-in",
			}),
			replace: true,
		});
	}, [redirecting, navigate]);

	return redirecting;
}

