describe('signInSearch', () => {
  // The /auth/login route validates seven keys and TanStack's typed navigate
  // wants the whole shape present. Every omitted key must still be spelled as
  // `undefined` — that requirement is exactly why call sites hand-copied the
  // literal, and why the org root was able to ship with no redirect at all.
  it('emits every key, defaulting to undefined', () => {
    expect(signInSearch()).toEqual({
      callbackUrl: undefined,
      mode: undefined,
      error: undefined,
      errorDescription: undefined,
      loginHint: undefined,
      invitationOrg: undefined,
      intent: undefined,
    });
  });

  it('passes through the options it is given', () => {
    expect(signInSearch({
      callbackUrl: '/acme/activity?tab=runs',
      intent: 'sign-in',
      invitationOrg: 'acme',
      loginHint: 'a@b.co',
    })).toEqual({
      callbackUrl: '/acme/activity?tab=runs',
      mode: undefined,
      error: undefined,
      errorDescription: undefined,
      loginHint: 'a@b.co',
      invitationOrg: 'acme',
      intent: 'sign-in',
    });
