describe('currentCallbackUrl', () => {
  const prev = window.location.pathname + window.location.search;
  afterEach(() => window.history.replaceState({}, '', prev));

  it('captures the path and query', () => {
    window.history.replaceState({}, '', '/acme/activity?tab=runs');
    expect(currentCallbackUrl()).toBe('/acme/activity?tab=runs');
  });

  // On a per-org subdomain the router works in `/${owner}`-prefixed paths while
  // the URL bar stays unprefixed. Reading the browser location (not the router)
  // is what keeps the post-login bounce from double-prefixing to /acme/acme.
  it('reads the unprefixed browser path a subdomain actually shows', () => {
    window.history.replaceState({}, '', '/');
    expect(currentCallbackUrl()).toBe('/');
  });
});

describe('useAnonymousSignInRedirect', () => {
  function Probe(props: { active: boolean; owner?: string }) {
    const redirecting = useAnonymousSignInRedirect(props);
    return <span data-testid="state">{String(redirecting)}</span>;
  }

  it('does not navigate while inactive', () => {
    const { getByTestId } = render(<Probe active={false} owner="acme" />);
    expect(navigateSpy).not.toHaveBeenCalled();
    expect(getByTestId('state').textContent).toBe('false');
  });

  it('navigates to sign-in carrying a callback back to here', () => {
    const prev = window.location.pathname + window.location.search;
    window.history.replaceState({}, '', '/acme');
    try {
      const { getByTestId } = render(<Probe active owner="acme" />);
      expect(navigateSpy).toHaveBeenCalledWith({
        to: '/auth/login',
        search: signInSearch({ callbackUrl: '/acme', intent: 'sign-in' }),
        replace: true,
      });
      expect(getByTestId('state').textContent).toBe('true');
    } finally {
      window.history.replaceState({}, '', prev);
    }
  });

  // A public org renders anonymously by design; SSR only injects a bootstrap
  // for one. Bouncing those visitors to sign-in would make public pages
  // unreachable while signed out.
  it('leaves a public org alone when SSR injected its bootstrap', () => {
    bootstrap.value = { ownerSlug: 'acme' };
    const { getByTestId } = render(<Probe active owner="acme" />);
    expect(navigateSpy).not.toHaveBeenCalled();
    expect(getByTestId('state').textContent).toBe('false');
  });

  it('still redirects when the bootstrap belongs to a different owner', () => {
    bootstrap.value = { ownerSlug: 'other-org' };
    render(<Probe active owner="acme" />);
    expect(navigateSpy).toHaveBeenCalledTimes(1);
  });
});

