import { chromium } from 'playwright';

const BASE = 'http://127.0.0.1:5199';
const OWNER = 'local-install';

const results = [];
function check(name, pass, detail) {
  results.push({ name, pass, detail });
  console.log(`${pass ? 'PASS' : 'FAIL'}  ${name}\n      ${detail}`);
}

const browser = await chromium.launch();

// Anonymous, cookie-free context — the expired/absent-session case.
const ctx = await browser.newContext();
const page = await ctx.newPage();

const bodies = [];
page.on('response', async (r) => {
  if (r.url().includes('/api/') && r.status() === 401) bodies.push(r.url());
});

// 1. Bare org root — the subdomain landing route, and the reported bug.
await page.goto(`${BASE}/${OWNER}`, { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
const rootUrl = new URL(page.url());
check(
  'bare org root redirects an anonymous visitor to sign-in',
  rootUrl.pathname === '/auth/login',
  `landed on ${rootUrl.pathname}${rootUrl.search}`
);
check(
  'callbackUrl points back at the org root',
  rootUrl.searchParams.get('callbackUrl') === `/${OWNER}`,
  `callbackUrl=${rootUrl.searchParams.get('callbackUrl')}`
);
const bodyText = await page.locator('body').innerText();
check(
  'no raw auth error is rendered',
  !/Couldn't load the workspace builder|Use OAuth or API key/i.test(bodyText),
  `body starts: ${bodyText.slice(0, 80).replace(/\n/g, ' ')}`
);
check(
  'the sign-in form is actually on screen',
  /sign in|continue with|email/i.test(bodyText),
  `body starts: ${bodyText.slice(0, 80).replace(/\n/g, ' ')}`
);

// 2. A deep owner page — should preserve where the user was headed.
await page.goto(`${BASE}/${OWNER}/activity?tab=runs`, { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
const deepUrl = new URL(page.url());
check(
  'deep owner page also redirects',
  deepUrl.pathname === '/auth/login',
  `landed on ${deepUrl.pathname}`
);
check(
  'callbackUrl preserves the deep path AND its query',
  deepUrl.searchParams.get('callbackUrl') === `/${OWNER}/activity?tab=runs`,
  `callbackUrl=${deepUrl.searchParams.get('callbackUrl')}`
);

// 3. The login page itself must not bounce (no redirect loop).
const hops = [];
page.on('framenavigated', (f) => {
  if (f === page.mainFrame()) hops.push(new URL(f.url()).pathname);
});
await page.goto(`${BASE}/auth/login`, { waitUntil: 'networkidle' });
await page.waitForTimeout(2000);
check(
  'login page is stable (no redirect loop)',
  new URL(page.url()).pathname === '/auth/login' && hops.filter((h) => h === '/auth/login').length <= 2,
  `nav hops: ${JSON.stringify(hops)}`
);

await browser.close();

const failed = results.filter((r) => !r.pass);
console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
process.exit(failed.length ? 1 : 0);

